/* Base styles: Mobile-First (< 768px) */
.nav-menu {
  display: flex;
  flex-direction: column;
  gap: 12px;
  padding: 16px;
  background-color: #1e293b;
}

.nav-menu a {
  color: #f8fafc;
  text-decoration: none;
  padding: 8px 12px;
}

/* Breakpoint Media Query: Applied at 768px (Tablets/Desktops) and wider */
@media (min-width: 768px) {
  .nav-menu {
    flex-direction: row;
    justify-content: flex-end;
    align-items: center;
    gap: 24px;
  }
}
